css:
/* ==== INTERFACE ====
方向：依据 02-swiss 瑞士国际主义排版，结合地铁导视系统的理性网格、高反差无衬线字阶、明确线框和几何色块。建立清晰的中英文轴线对齐，为高中生出行工作坊提供直观、严谨且易于对比的地铁路线与耗时分解分析。
reference style:02-swiss
借鉴特征：严谨的网格对齐、强反差无衬线排印（中文重黑 + 英文窄黑）、清晰硬朗的直角线框、非对称强调色块（红/深蓝/中性灰地铁线路标识色），摒弃繁复装饰与柔化阴影。
token --bg：页面底色 #f5f6f8（极淡冷灰，类似现代公共导视底板）。
token --text：正文字色 #11141a（高对比墨黑）。
token --text-muted：次级说明字色 #5f6672。
token --font-sans：正文与控件字体 'NTF-inter', 'NTF-noto-sans-sc', system-ui, sans-serif。
token --font-display：展陈与窄体英文标题 'NTF-barlow-condensed', 'NTF-noto-sans-sc', sans-serif。
字阶：
  --fs-hero: 64px / 行高 1.05 / 强调大标题（封面/引入大问句）
  --fs-h1: 38px / 行高 1.15 / 普通页题名
  --fs-h2: 24px / 行高 1.25 / 模块与分栏标题
  --fs-lead: 20px / 行高 1.45 / 核心导语与重点结论
  --fs-body: 16px / 行高 1.50 / 正文与解析
  --fs-sec: 14px / 行高 1.45 / 次级说明与参数注释
  --fs-label: 13px / 行高 1.20 / 线路标签与胶囊标记
  --fs-tick: 12px / 行高 1.10 / 数据刻度与时间轴数字
class .nt-title：普通页题名，字重 800，紧凑行高，配合瑞士式前置斜杠或编号。
class .nt-display：超大字号英文/数字，采用 Barlow Condensed 紧凑排布。
class .nt-lead：导语段落，用于引出核心悖论或决策规则。
class .nt-panel：瑞士结构化直角框，纯白底、精细灰色边框与硬朗内边距，提供严谨对齐基准。
class .nt-tag / .nt-badge：地铁线路式小标签，支持线色与粗黑文字组合。
class .nt-btn：直角硬朗控制按钮，清晰聚焦态与按下态（包含 aria-pressed 支持）。
class .nt-table：高可读性理性对比表，含等宽数字排版与明确水平分割线。
class .nt-formula：时间公式分解容器（总时间 = 乘车 + 候车 + 换乘步移）。
variant opening：开篇封面态，引入深墨色非对称色块区与强烈反差对比。
默认：无 data-variant；底色为干净导视浅灰，带有克制精密的 24px 逻辑点阵/对齐基底。
==== /INTERFACE ==== */

/* 1. 字体声明 */
@font-face {
  font-family: "NTF-noto-sans-sc";
  src: url("fonts/library/noto-sans-sc/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-0.ttf");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-1.ttf");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-barlow-condensed";
  src: url("fonts/library/barlow-condensed/face-2.ttf");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-0.ttf");
  font-weight: 100 900;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "NTF-inter";
  src: url("fonts/library/inter/face-1.ttf");
  font-weight: 100 900;
  font-style: italic;
  font-display: swap;
}

/* 2. 核心 Token */
:root {
  /* 颜色系统 */
  --bg: #f4f5f7;
  --bg-subtle: #ebedf2;
  --panel-bg: #ffffff;
  --text: #11141a;
  --muted: #5d6573;
  --line: #d2d7e0;
  --line-strong: #11141a;
  --focus: #d92314;

  /* 交通线路典型标识色 */
  --line-red: #d92314;
  --line-blue: #005bb7;
  --line-green: #0a8451;
  --line-orange: #e06d00;
  --line-yellow: #f2a900;
  --line-purple: #782b90;

  /* 字体族 */
  --font-sans: "NTF-inter", "NTF-noto-sans-sc", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-display: "NTF-barlow-condensed", "NTF-noto-sans-sc", sans-serif;
  --font-mono: "NTF-inter", monospace;

  /* 字阶与排版 */
  --fs-hero: 58px;
  --fs-h1: 36px;
  --fs-h2: 22px;
  --fs-lead: 18px;
  --fs-body: 15px;
  --fs-sec: 13px;
  --fs-label: 12px;
  --fs-tick: 11px;

  /* 间距与尺寸 */
  --gap-xs: 6px;
  --gap-sm: 12px;
  --gap-md: 20px;
  --gap-lg: 32px;
  --gap-xl: 48px;

  /* 共享绘图参数供 SVG / Canvas 引用 */
  --chart-line-width: 4px;
  --chart-node-size: 14px;
  --chart-node-inner: 6px;
}

/* 3. 舞台与基础排印 */
#stage {
  background-color: var(--bg);
  background-image: 
    linear-gradient(to right, rgba(0, 0, 0, 0.035) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(0, 0, 0, 0.035) 1px, transparent 1px);
  background-size: 40px 40px;
  background-position: 0 0;
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  box-sizing: border-box;
}

/* 开篇变体 (Opening Variant)：瑞士风高对比非对称布局支持 */
html[data-variant="opening"] #stage {
  background-color: #f7f8fa;
  background-image:
    linear-gradient(90deg, #11141a 0%, #11141a 38%, transparent 38%),
    linear-gradient(to right, rgba(255, 255, 255, 0.05) 1px, transparent 1px);
  background-size: 100% 100%, 40px 40px;
}

/* 4. 排版角色类 */
.nt-hero {
  font-family: var(--font-sans);
  font-size: var(--fs-hero);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.02em;
  margin: 0;
  color: var(--text);
}

.nt-hero:lang(en) {
  font-family: var(--font-display);
  letter-spacing: 0.02em;
  text-transform: uppercase;
}

.nt-title {
  font-family: var(--font-sans);
  font-size: var(--fs-h1);
  font-weight: 800;
  line-height: 1.18;
  letter-spacing: -0.015em;
  margin: 0;
  color: var(--text);
  display: flex;
  align-items: baseline;
  gap: 12px;
}

.nt-title::before {
  content: "/";
  color: var(--line-red);
  font-weight: 900;
  font-size: 1.1em;
  line-height: 0.8;
}

.nt-subtitle {
  font-size: var(--fs-h2);
  font-weight: 700;
  line-height: 1.3;
  margin: 0;
  color: var(--text);
}

.nt-lead {
  font-size: var(--fs-lead);
  font-weight: 500;
  line-height: 1.45;
  color: var(--muted);
  margin: 0;
}

.nt-body {
  font-size: var(--fs-body);
  line-height: 1.55;
  color: var(--text);
  margin: 0;
}

.nt-meta {
  font-size: var(--fs-sec);
  line-height: 1.4;
  color: var(--muted);
}

.nt-display-num {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 800;
  line-height: 1.0;
  letter-spacing: 0.02em;
  color: var(--text);
  font-variant-numeric: tabular-nums;
}

/* 5. 结构与容器（瑞士国际主义直角线框与色块） */
.nt-grid-frame {
  display: grid;
  gap: var(--gap-md);
  box-sizing: border-box;
}

.nt-panel {
  background: var(--panel-bg);
  border: 1.5px solid var(--line);
  box-sizing: border-box;
  padding: 24px;
  position: relative;
}

.nt-panel-header {
  border-bottom: 1.5px solid var(--line);
  padding-bottom: 12px;
  margin-bottom: 16px;
  display: flex;
  justify-content: space-between;
  align-items: baseline;
}

.nt-panel-dark {
  background: #11141a;
  color: #ffffff;
  border: 1.5px solid #11141a;
}

.nt-panel-dark .nt-subtitle,
.nt-panel-dark .nt-display-num {
  color: #ffffff;
}

.nt-panel-dark .nt-meta {
  color: #a0a7b4;
}

.nt-panel-dark .nt-panel-header {
  border-bottom-color: rgba(255, 255, 255, 0.2);
}

.nt-panel-accent {
  background: var(--line-red);
  color: #ffffff;
  border: 1.5px solid var(--line-red);
}

.nt-panel-accent .nt-subtitle,
.nt-panel-accent .nt-display-num,
.nt-panel-accent .nt-lead {
  color: #ffffff;
}

/* 6. 交通线路导视标签与标记 */
.nt-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-label);
  font-weight: 700;
  padding: 3px 8px;
  border-radius: 2px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1;
}

.nt-tag-line1 {
  background-color: var(--line-red);
  color: #ffffff;
}

.nt-tag-line2 {
  background-color: var(--line-blue);
  color: #ffffff;
}

.nt-tag-line3 {
  background-color: var(--line-green);
  color: #ffffff;
}

.nt-tag-line4 {
  background-color: var(--line-orange);
  color: #ffffff;
}

.nt-tag-outline {
  background: transparent;
  border: 1.5px solid var(--line-strong);
  color: var(--line-strong);
}

.nt-badge-flag {
  display: inline-block;
  background: #11141a;
  color: #ffffff;
  font-size: var(--fs-tick);
  font-weight: 800;
  padding: 2px 6px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

/* 7. 公共交通比较表与指标分解 */
.nt-compare-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--fs-body);
  text-align: left;
}

.nt-compare-table th {
  font-size: var(--fs-sec);
  font-weight: 700;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  border-bottom: 2px solid var(--line-strong);
  padding: 10px 12px;
}

.nt-compare-table td {
  padding: 14px 12px;
  border-bottom: 1px solid var(--line);
  font-variant-numeric: tabular-nums;
  vertical-align: middle;
}

.nt-compare-table tr:hover td {
  background-color: rgba(0, 91, 183, 0.04);
}

.nt-compare-table tr.is-active td {
  background-color: rgba(217, 35, 20, 0.06);
  font-weight: 700;
}

.nt-time-bar {
  display: flex;
  height: 24px;
  border-radius: 2px;
  overflow: hidden;
  background: #e1e4ea;
  width: 100%;
}

.nt-time-bar-ride {
  background: var(--line-blue);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
}

.nt-time-bar-wait {
  background: var(--line-yellow);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #111;
  font-size: 11px;
  font-weight: 700;
}

.nt-time-bar-transfer {
  background: var(--line-red);
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 11px;
  font-weight: 700;
}

/* 8. 控制器与交互组件（直角、高对比度、符合无障碍） */
.nt-btn-group {
  display: flex;
  gap: 8px;
}

.nt-btn {
  appearance: none;
  border: 1.5px solid var(--line-strong);
  background: #ffffff;
  color: var(--line-strong);
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  font-weight: 700;
  padding: 8px 16px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
  line-height: 1.2;
}

.nt-btn:hover {
  background: #11141a;
  color: #ffffff;
}

.nt-btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.nt-btn[aria-pressed="true"],
.nt-btn.is-active {
  background: var(--line-red);
  border-color: var(--line-red);
  color: #ffffff;
}

/* 9. 地铁拓扑图通用 SVG 样式支持 */
.nt-topo-map {
  width: 100%;
  height: 100%;
  display: block;
}

.nt-topo-line {
  fill: none;
  stroke-width: var(--chart-line-width);
  stroke-linecap: round;
  stroke-linejoin: round;
}

.nt-topo-station {
  fill: #ffffff;
  stroke: #11141a;
  stroke-width: 2.5px;
  r: 5px;
  cursor: pointer;
  transition: r 0.2s ease, stroke 0.2s ease;
}

.nt-topo-station.is-transfer {
  stroke-width: 3.5px;
  r: 7px;
}

.nt-topo-station:hover {
  r: 8px;
  stroke: var(--line-red);
}

.nt-topo-label {
  font-family: var(--font-sans);
  font-size: var(--fs-tick);
  font-weight: 600;
  fill: var(--text);
  user-select: none;
}
